    "full": "苏轼《南乡子·送述古》写道：“归路晚风清。”\n词人送别之后回程，写到清清晚风。借词里的这一缕风，送各位一句珍重：今天相聚尽兴，回去一路安稳，来日还有好时光。",
    "english": "To a lovely gathering, a safe journey home, and more happy times to come.",
    "translation": "词人送别之后回程，写到清清晚风。借词里的这一缕风，送各位一句珍重：今天相聚尽兴，回去一路安稳，来日还有好时光。",
    "reason": "逐条语义审校：修正原意与当前发言的衔接，去掉孤立贴句、重复敬语或训诫口气。",
