    "full": "苏轼《蝶恋花·密州上元》里有一句：“明月如霜，照见人如画。”\n词人回想元宵灯月，也把人写得明亮。咱们一家人的好光景，就在同桌的说笑里。这杯敬团聚，愿往后年节有欢，平常日子也常能相见。",
    "english": "To the warmth of family around one table, at festivals and on ordinary days alike.",
