    "full": "苏轼《浣溪沙·游蕲水清泉寺》写道：“谁道人生无再少？”\n词人见溪水西流，心气也跟着振作。我借这份兴致敬各位：愿手头的事越做越顺，心里想尝试的，也有合适的机会开始。",
