    "full": "苏轼《卜算子·黄州定慧院寓居作》写道：“谁见幽人独往来，缥缈孤鸿影。”\n孤鸿的身影，让人想起有人理解的可贵。谢谢你这一杯，也谢谢你的好意。我回敬你，愿开心有人分享，心事有人肯听，平常日子里常有温暖相伴。",
    "english": "Thank you for your kindness. May you have people to share your joy with and someone who will listen when you need it.",
    "translation": "孤鸿的身影，让人想起有人理解的可贵。谢谢你这一杯，也谢谢你的好意。我回敬你，愿开心有人分享，心事有人肯听，平常日子里常有温暖相伴。",
    "reason": "逐条语义审校：修正原意与当前发言的衔接，去掉孤立贴句、重复敬语或训诫口气。",
    "source": "r04-ci-13",
