    "full": "辛弃疾《西江月·夜行黄沙道中》里有一句：“七八个星天外，两三点雨山前。”\n词人夜行，路一转，认出了熟悉的茅店。那份意外的亲切，今天也想借来敬各位：愿聊着聊着，发现共同的趣味，从初识走到熟悉。",
