    "full": "辛弃疾《贺新郎·甚矣吾衰矣》里有一句：“知我者，二三子。”\n这句写知心朋友，我今天也想借它谢你。谢谢你的祝福，也谢谢这份说得上话的亲切。这杯回敬你，愿相见有欢喜，平日有惦念。",
    "english": "Thank you for your warm wishes and the ease of good conversation. Here is to staying close, even when life is busy.",
    "translation": "这句写知心朋友，我今天也想借它谢你。谢谢你的祝福，也谢谢这份说得上话的亲切。这杯回敬你，愿相见有欢喜，平日有惦念。",
    "reason": "逐条语义审校：修正原意与当前发言的衔接，去掉孤立贴句、重复敬语或训诫口气。",
