    "full": "欧阳炯《南乡子·画舸停桡》写道：“笑指芭蕉林里住。”\n词里一个回眸的笑，让相识多了几分亲切。今天很高兴认识你，咱们也从轻松的聊天开始。这杯敬今天这一面，愿有好话题，也有好心情。",
    "english": "It is a pleasure to meet you. Here is to an easy conversation, shared interests, and a lovely time together.",
