    "full": "牛希济《生查子·春山烟欲收》里有一句：“语已多，情未了。”\n词写恋人惜别，我只借这六个字，说今天相聚的意犹未尽。一顿饭说不完的话，就留给下回。这杯敬各位，愿回去平安，往后见面有期。",
    "english": "There is always more to talk about. Have a safe journey home, and let us save some stories for next time.",
    "translation": "词写恋人惜别，我只借这六个字，说今天相聚的意犹未尽。一顿饭说不完的话，就留给下回。这杯敬各位，愿回去平安，往后见面有期。",
    "reason": "逐条语义审校：修正原意与当前发言的衔接，去掉孤立贴句、重复敬语或训诫口气。",
