    "short": "《世说新语》写郭林宗访黄叔度，有这样一句：“其器深广，难测量也。”郭林宗以深广的水泽赞黄叔度的器量。我借这份温厚敬您，愿您平日有闲趣，身边有知心人，家人常相伴，心里常安稳。",
