  "r04-story-12-2": {
    "short": "《世说新语》记阮修答问，谈到老庄与圣教异同，他说：“将无同？”意思是：莫非也有相通之处？三个字留下“三语掾”的谈资。我今天也说短一点：谢谢你这杯，祝你忙有所成，闲有所乐。",
    "full": "《世说新语》里，王夷甫问阮修老庄与圣教的异同，阮修答：“将无同？”——莫非也有相通的地方？\n这段“三语掾”的故事很有意思。我今天也把心意说简短：谢谢你的祝福，这杯回敬你，愿忙有所成，闲有所乐，想见的人常能见着。",
    "english": "Thank you for your kind wishes. May your work go well, your free time be joyful, and good company never be far away.",
    "translation": "谢谢你的祝福，愿忙有所成，闲有所乐，想见的人常能见着。",
    "reason": "逐条审校：让引句、原意与眼前的祝愿自然衔接，修正角色和语气。",
    "tip": "先说清引句或故事的来历，再接眼前的心意。原作背景与本次借意在出处分开说明。"
  },
