    "full": "《诗经·瓠叶》写道：“幡幡瓠叶，采之亨之。”\n一把家常菜，也盛着愿意待客的诚意。今天领受这份心意，很高兴。这杯谢谢你的款待，愿往后来来往往，总有饭可约，有话可聊。",
