  "r04-ci-12-1": {
    "short": "苏轼说：“敲门都不应，倚杖听江声。”词里，夜归的人在门外倚杖，听江水流过。今天借这份从容敬朋友：愿咱们忙有所得，闲有所爱，见面有说不完的话。",
    "full": "苏轼在《临江仙·夜归临皋》里写：“敲门都不应，倚杖听江声。”\n词中醉归的人，遇上家童熟睡、敲门未应，便倚杖听江。那份身不由己之外的自在，让人留恋。今天借这份从容敬朋友，愿咱们忙有所得，闲有所爱，相聚时总有说不完的话。",
    "english": "To rewarding days, time for what we love, and the pleasure of seeing good friends.",
    "translation": "愿忙有所得，闲有所爱，朋友相聚有说不完的话。",
    "reason": "逐条语义审校：修正原意与当前发言的衔接，去掉孤立贴句、重复敬语或训诫口气。",
    "tip": "先说清引句或故事的来历，再接眼前的心意。原作背景与本次借意在出处分开说明。"
  },
