    "full": "《诗经·南有嘉鱼》写道：“君子有酒，嘉宾式燕以乐。”\n诗写宾主相聚的欢喜，今天有朋友同桌，也是一样的高兴。这杯敬大家，愿饭吃得有味，话聊得知心，往后有空常聚。",
