    "full": "借《诗经》的一句：“适子之馆兮。”好意有时落在一件衣、一顿饭里，不声张，却让人记很久。今天这杯，敬一家人平常的照应。\n这杯敬家人，愿彼此多照应，日常常舒心。",
    "english": "To the small kindnesses that make ordinary days feel warmer.",
