    "full": "《世说新语》里，顾长康吃甘蔗先吃尾，说是“渐至佳境”。\n甘蔗都懂把甜头放后面，咱们的好事也不急着一次到齐。\n这一杯敬你，愿你忙的时候有收获，闲的时候有滋味。",
    "english": "May life grow sweeter, one good day at a time. Here is to you, to rewarding work and happy days.",
