    "full": "范成大写舟行：“画舫夷犹湾百转，横塘塔近依前远。”\n读到这里，喜欢的是小舟回湾的从容。借这一点悠然，珍惜今天能坐下来相聚的时光。\n今天谢谢你的张罗，让相聚有着落，也让我们有空坐下来好好说话。这杯敬你。",
