    "full": "常建在《题破山寺后禅院》里写：“曲径通幽处，禅房花木深。”\n诗里有越走近、越觉清幽的景致。人与人的照应，有时也在细微处见用心。今天想认真谢谢你，张罗这一顿饭，让相聚有了着落。这杯敬你，愿往后你也常有轻松做客的时候。",
