    "full": "《诗经·有杕之杜》写道：“中心好之，曷饮食之。”我借其中愿意好好待人的心意，欢迎今天同桌的各位。热菜慢慢尝，近况慢慢聊，愿大家来了自在，走时尽兴。",
    "english": "Welcome, everyone. I hope you enjoy the meal, feel at home, and leave with a happy memory.",
    "translation": "借愿意好好待客的心意，欢迎各位，愿饭菜合口，聊天尽兴。",
