    "full": "《世说新语》里，王子猷暂住也要种竹，人问缘故，他说：“何可一日无此君？”喜欢的事，原来也能这样让人惦记。今天敬大家，愿忙有收获，闲有雅兴，日常有自己的小欢喜。",
    "english": "To rewarding days, interests we love, and small pleasures that make life our own.",
    "translation": "愿忙有收获，闲有雅兴，日常有自己的小欢喜。",
